Definition BCOPY_STACK : Z := 80.

(* [comment removed for export] *)
Definition mb_b1 (b : Z) (es : list mbe) (insz n x : Z) : Z * Z :=
  if mb_need es insz n then
    (if mb_full es insz then (x + 24, n) else (mb_lasta b es + 24 + mb_outpos es insz, mb_cap es - insz))
  else (mb_lasta b es + 24 + mb_outpos es insz, n).
Definition mb_b2 (b : Z) (es : list mbe) (insz n x : Z) : Z * Z :=
  if mb_need es insz n && negb (mb_full es insz) then (x + 24, insz + n - mb_cap es) else mb_b1 b es insz n x.
(* [comment removed for export] *)

Definition bcopyW (lo : Z) (sp : word) (b : Z) (es : list mbe) (insz n x : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp);
   (fst (mb_b1 b es insz n x), fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x));
   (fst (mb_b2 b es insz n x), fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x))]%Z.

Definition bcopy_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (tbp tep srp cbp src b : Z) (es : list mbe) (insz n x lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz n) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (bcopyW lo sp b es insz n x) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' tbp [C8 (wz srp); C8 (wz (mb_mid_out b es insz x))]
    /\ rw_cells rsegs m' tep [C8 (wz srp); C8 (wz (b + 8))]
    /\ rw_cells rsegs m' srp (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n))
    /\ rw_cells rsegs m' cbp [C8 (wz src); C8 (wz n)]
    /\ bytes_at rsegs m' src bs
    /\ MBmid m' b es insz n x.

Definition bcopy_stmt : Prop := forall (tbp tep srp cbp src b : Z) (es : list mbe) (insz n x lo : Z) (bs : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a5 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  MBmid m b es insz n x -> mb_ok es insz -> 1 <= n -> insz + n <= 2^30 ->
  rw_cells rsegs m tbp [C8 (wz srp); C8 (wz (mb_mid_out b es insz x))] ->
  rw_cells rsegs m tep [C8 (wz srp); C8 (wz (b + 8))] ->
  rw_cells rsegs m srp (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n)) ->
  rw_cells rsegs m cbp [C8 (wz src); C8 (wz n)] ->
  bytes_at rsegs m src bs -> zlength bs = n ->
  (forall x' s', In (x', s') (mb_put_es es insz n x) -> src + n <= x' \/ x' + 24 + s' <= src) ->
  (src + n <= lo \/ bv_unsigned sp <= src) ->
  bv_unsigned sp <= tbp -> bv_unsigned sp <= tep -> bv_unsigned sp <= srp -> bv_unsigned sp <= cbp -> bv_unsigned sp <= b ->
  tbp + 16 <= 2^64 -> tep + 16 <= 2^64 -> srp + 40 <= 2^64 -> cbp + 16 <= 2^64 ->
  stk rsegs m lo (bv_unsigned sp) -> lo + BCOPY_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (bcopy_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc tbp tep srp cbp src b es insz n x lo bs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 (wz tbp) (wz tep) (wz cbp) a5 (Z_to_bv 64 (2^64 - 1)) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BUFFER_COPY_MB) fc None m (seg_rom rsegs)).
